#define JSON_TRACEF(f, fmt, ...) do {                                       \
     if ((f) == NULL) {                                                      \
         printf(JSON_COL " [%-35.35s] " fmt JSON_NL, __func__, ##__VA_ARGS__);  \
     } else {                                                                \
         const struct connflow *_cf;                                         \
         const struct streamflow *_sf;                                       \
         if (const_uflow_expand((f), &_cf, &_sf) == uflow_type_connflow) {   \
             printf(JSON_COL " [%-35.35s]:%d %p [%c] " fmt JSON_NL, __func__, __LINE__,       \
                 (union uflow *)(f),                                         \
                 uflow_is_clientside((union uflow *)(f)) ? 'C' : 'S',        \
                         ##__VA_ARGS__);                                     \
         } else {                                                            \
             printf(JSON_COL " [%-35.35s]:%d %p [%c:%d] " fmt JSON_NL, __func__,__LINE__,    \
                 (union uflow *)(f),                                         \
                 uflow_is_clientside((union uflow *)(f)) ? 'C' : 'S',        \
                 _sf->stream_id, ##__VA_ARGS__);                             \
         }                                                                   \
     }                                                                       \
 } while(/*CONSTCOND*/0)
 #else
 #define JSON_TRACEF(f, fmt, ...)                      /* Nothing. */
 #endif

