#ifndef _HUDFILTER_H
#define _HUDFILTER_H

/*
 * These methods are implemented by all base nodes, currently
 * TCP and UDP
 */
enum hudnode_method {
    HUDNODE_METHOD_GET_FLOW,
    HUDNODE_METHOD_COUNT
};

/*
 * The hudsucker framework is a modular system for networking within
 * the microkernel. The processing components in the system are called
 * filters. Each filter has a process routine that processes ingress
 * packets from the lower-lever filter and egress packets from the
 * upper-level filter.  Each filter also has a handler that processes
 * event notifications from the lower-level filter and control
 * messages from the upper-level filter. To put it another way, a
 * hudfilter is a link in a packet-processing chain.
 */
struct hudproxy;
struct profile_key;
struct tmevt;
struct xbuf;
struct pkt_queue;
struct hudnode;
struct hudfilter;
struct profile_listener;
union uflow;

typedef err_t (*hud_init)(struct hudfilter *this, struct hudproxy *proxy);
typedef void  (*hud_uninit)(struct hudfilter *this);
typedef void  (*hud_handler)(struct hudnode *node, hud_msg_t msg,
        struct connflow *cf, void *data);
typedef err_t (*hud_processor)(struct hudnode *node, struct connflow *cf,
        struct xbuf *xb);
typedef err_t (*hud_process_pkt)(struct hudnode *node, struct connflow *cf,
        struct packet *pkt);
typedef void (*stream_handler)(struct hudnode *snode, hud_msg_t msg,
        union uflow *uf, void *data);
typedef err_t (*stream_processor)(struct hudnode *node,
        union uflow *uf, struct xbuf *xb);

/*
 * Bottom level filters begin at 0 and increase to UINT16_MAX
 * at the proxy filters.
 */
#define HUDFILTER_BOTTOM_INDEX               0
#define HUDFILTER_PROXY_INDEX                (UINT16_MAX - 1)
#define HUDFILTER_PROXY_MOCK_INDEX           UINT16_MAX
#define HUDFILTER_MINOR_INC                  100

#include <local/sys/inline_tmm.h>
#include "hudfilter_order.h"

/*
 * Return the filter clientside index given position.
 */
UINT16 filter_client_index(enum hudfilter_clientside_order position);

/*
 * Return the filter serverside index given position.
 */
UINT16 filter_server_index(enum hudfilter_serverside_order position);

/*
 * Specification for a hudfilter object.
 */
struct hudfilter_spec {
    const char *name;
    UINT16      scb_sz;
    UINT16      pcb_sz;
    UINT16      private_sz;
    hud_init    init;
    hud_uninit  uninit;
    union {
        hud_handler handler;
        stream_handler s_handler;
    };
    union {
        void       *ingress;
        stream_processor s_ingress;
    };
    union {
        void       *egress;
        stream_processor s_egress;
    };
    void       *scratch;
    BOOL        f_bottom : 1;
    BOOL        f_top : 1;
    BOOL        f_clientside : 1;
    BOOL        f_serverside : 1;
    BOOL        f_disabled : 1;
    BOOL        f_no_prime : 1;
    BOOL        f_orbit : 1;
    UINT16      clientside_position;
    UINT16      serverside_position;
};

/**
 * Hudfilter instance (connflow processing node).
 *
 * This block (including filter context) is instantiated once per
 * connection and manages connection flow.  The functions and linkage
 * are initialized from the hudfilter template, but may be overriden as
 * packets are processed and connflow state changes.
 *
 * Usage of hudnode pointers must be through hudnode_swapref calls, as all
 * stored hudnode pointers must be properly refcounted.  Proper usage is
 * always some form of this:
 *   hudnode_swapref(&old_ptr, new_ptr);
 *
 * If old_ptr didn't previously have a node in it, make sure that the value
 * was NULL.  Calling setref or release directly is discouraged, as most
 * interactions with hudnode pointers require properly releasing the previous
 * node when storing a new one.
 */
struct hudnode {
    /* Pulled from the hudfilter */
    union {
        hud_handler         h_handler;
        stream_handler      h_s_handler;
    };
    union {
        hud_processor       ingress;    /*!< Ingress processor. */
        hud_process_pkt     ingress_btm;
        stream_processor    s_ingress;
    };
    union {
        hud_processor       egress;     /*!< Egress processor. */
        hud_process_pkt     egress_pkt;
        stream_processor    s_egress;
    };

    /* Chain references. */
    struct hudnode     *above;
    struct hudnode     *below;

    /* Reference counting. */
    UINT32              ref;

    /* Size of the allocated ctx, 64 byte aligned */
    UINT16              ctx_sz;

    /* System flags copied from the old hudfilter object */
    BOOL                f_disabled : 1;
    BOOL                f_clientside : 1;
    BOOL                f_serverside : 1;
    BOOL                f_top : 1;
    BOOL                f_bottom : 1;
    /* Flags that can be commonly used by multiple hudfilters. */
    BOOL                f_no_abort : 1;
    /* Flags specific to the new hudnode implementation. */
    BOOL                f_active : 1;   /* Per connection node. */
    BOOL                f_ctx : 1;      /* Valid context. */
    /* Prevent the framework from priming the node by default. */
    BOOL                f_no_prime : 1;
    BOOL                f_stream : 1;   /* Stream context */
    BOOL                f_orbit : 1;    /* Orbit overrides handlers */

    /* Spare flags for use by filters. Use low numbers first. */
    BOOL                f_scratch1 : 1;

    BOOL                pad : 4;        /* Reserved, not for you! */

    /* Fixed outward references. */
    void               *private;        /* PFB (filter->private). */
    void               *parent;         /* parent context */

    BYTE                ctx[];          /* PCB. */
};

/*
 * Max pcb size is bound by the pcb_sz bits above (6) and cache aligned, which
 * means it's allocated in blocks of 64.
 */
#define HUD_PCB_SZ_MAX 4032


/*
 * hudfilter
 *
 * f_top : Set to TRUE in hudproxy_new() for filters within a hudproxy.
 * f_bottom : Set to TRUE for bottom-level filters.
 * f_disabled : Set to TRUE for filters that are initially disabled.
 * f_clientside : Set to TRUE for filters that belong on the clientside.
 * f_serverside : Set to TRUE for filters that belong on the serverside.
 *                Note that both clientside and serverside should be set
 *                if the filter belongs on both sides. If neither is set,
 *                then the chain position is determined by the profile.
 *                The flags are updated in hudfilter_init().
 * f_initialized : Set to TRUE if hudfilter_init() is successful.
 */
struct hudfilter_base {
    struct hud_typeid           *typeid;
    const char                  *name;

    /* Callbacks. */
    hud_init                     init;
    hud_uninit                   uninit;
    struct profile_listener     *pl;

    /* Owning configuration object. */
    struct hudproxy             *proxy;

    void                       *(*early_action)(struct listener *listener,
                                    struct packet *pkt, struct flow_key *key,
                                    struct hudfilter *filter,
                                    struct hudnode **node, void *fn);

    UINT16                       pcb_sz;
    UINT16                       scb_sz;
    UINT16                       clientside_position;
    UINT16                       serverside_position;
    UINT16                       private_sz:14;
    BOOL                         f_initialized : 1;
    BOOL                         f_deferred : 1;
};

struct hudfilter {
    struct hudnode node;
    struct hudfilter_base base;
    /* private initialization of the filter lives here. */
    /* Filter 'private' configuration. */
    BYTE            private[];
};

#define HUD_POPULATE_FILTER(tag, spec)                                      \
static RTTHREAD struct hudfilter tag;                                       \
static err_t hudfilter_populate_##tag(void);                                \
INIT_FUNC(INIT_CTOR + INIT_SUB_FIRST, hudfilter_populate_##tag);            \
static err_t hudfilter_populate_##tag(void)                                 \
{                                                                           \
    struct hudfilter *h                    = &tag;                          \
    h->base.name                           = spec.name;                     \
    h->base.pcb_sz                         = spec.pcb_sz;                   \
    h->base.scb_sz                         = spec.scb_sz;                   \
    h->base.private_sz                     = spec.private_sz;               \
    h->base.init                           = spec.init;                     \
    h->base.uninit                         = spec.uninit;                   \
    h->base.clientside_position            = spec.clientside_position;      \
    h->base.serverside_position            = spec.serverside_position;      \
    h->node.h_handler                      = spec.handler;                  \
    h->node.ingress                        = spec.ingress;                  \
    h->node.egress                         = spec.egress;                   \
    h->node.ref                            = 1;                             \
    h->node.f_disabled                     = spec.f_disabled;               \
    h->node.f_top                          = spec.f_top;                    \
    h->node.f_bottom                       = spec.f_bottom;                 \
    h->node.f_clientside                   = spec.f_clientside;             \
    h->node.f_serverside                   = spec.f_serverside;             \
    h->node.f_orbit                        = spec.f_orbit;                  \
    h->node.f_no_prime                     = spec.f_no_prime;               \
    h->node.private                        = h->private;                    \
    return ERR_OK;                                                          \
}

