/*
 * Search through a supplied chain in the direction specified for a filter
 * that matches TYPEID.
 */
#define hud_find_node(base, typeid, d) ({                                   \
    struct hudnode *_n = (base);                                            \
    while (_n != NULL) {                                                    \
        if (HUDNODE_TYPEID(_n) == typeid) {                                 \
            break;                                                          \
        }                                                                   \
                                                                            \
        _n = HUDNODE_ ## d(_n);                                             \
    }                                                                       \
    _n;                                                                     \
})

/*
 * Search through a supplied chain in the direction specified for a filter
 * that has the name name.
 */
#define hud_find_node_by_name(base, hud_name, d) ({                         \
    struct hudnode *_n = (base);                                            \
    struct hudfilter *_f;                                                   \
    while (_n != NULL) {                                                    \
        _f = HUDNODE_FILTER(_n);                                            \
        if ((HUDFILTER_NAME(_f) != NULL) &&                                 \
                (strcmp(HUDFILTER_NAME(_f), hud_name) == 0)) {              \
            break;                                                          \
        }                                                                   \
                                                                            \
        _n = HUDNODE_ ## d(_n);                                             \
    }                                                                       \
    _n;                                                                     \
})

/*
 * Find the farthest node in the given direction.
 */
#define hudnode_remote(node, d) ({                                          \
    struct hudnode *_n = (node);                                            \
    while (HUDNODE_ ## d(_n) != NULL) {                                     \
        _n = HUDNODE_ ## d(_n);                                             \
    }                                                                       \
    _n;                                                                     \
})

