#define HUD_MSG_QUEUE_DEPTH 4096

/*
 * Determine if this entry to the framework should be profiled.
 */

#define hud_enter(x) _hud_enter((uflow_fromconnflow(x)), 1)
#define hud_uf_enter(x) _hud_enter((x), 1)
#define hud_leave() _hud_leave(1)
#define hud_fast_leave() _hud_fast_leave()

#if LISTENER_CPU

#define hudq_drain_enter(x) _hud_enter((x), 0)
#define hudq_drain_leave() _hud_leave(0)

static inline BOOL
hud_profile_required(union uflow *uf)
{
    hud.profile_next = (1664525L * hud.profile_next) + 1013904223L;
    return ((hud.profile_next % LISTENER_CPU) == 0) &&
            (uf != NULL) && (uflow_get_listener_key(uf) != NULL);
}

/*
 * Start profile accounting.
 */
static inline void
hud_profile_start(struct listener_key *lk)
{
    hud.profile_start = read_cycle_counter();
    hud.profiled_listener_key = lk;
    listener_key_addref(lk);
}

/*
 * Stop profile accounting.
 */
static inline void
hud_profile_stop(void)
{
    struct listener_key *lk = hud.profiled_listener_key;
    if (lk != NULL) {
        lk->cycle_count += read_cycle_counter() - hud.profile_start;
        hud.profile_start = 0;
        hud.profiled_listener_key = NULL;
        listener_key_release(lk);
    }
}
#else

#define hudq_drain_enter(x) /* Nothing */
#define hudq_drain_leave() /* Nothing */
#define hud_profile_required(x) /* Nothing */
#define hud_profile_start(x) /* Nothing */
#define hud_profile_stop() /* Nothing */

#endif

/*
 * Perform actions required upon every entry to the hudsucker framework.
 *
 * @param   Related connflow, if any.
 */
static inline void
_hud_enter(union uflow *uf, unsigned increment)
{
    hud.depth += increment;
    /*
     * Don't need to check increment because this is either
     * called with increment = 1, in which case we want to check hud.depth
     * or with increment = 0 from hudQ_drain() in with case hud.depth is
     * always == 1
     */
#if LISTENER_CPU
    if ((hud.depth == 1) && hud_profile_required(uf)) {
        /*
         * If we are here, hud_profile_required() has checked
         * listener_key for NULL.
         */
        hud_profile_start(uflow_get_listener_key(uf));
    }
#endif
}

/*
 * Perform actions required upon every exit from the hudsucker framework.
 *
 * If decrement == TRUE, we want to dec hud.depth and check hud.depth==0
 * before calling hud_profile_stop() and call hudQ_drain if hud.q_count>0.
 *
 * If decrement == FALSE, we dont check anything, we call hud_profile_stop and
 * don't call hudQ_drain().
 *
 * @param   Related connflow, if any.
 */
static inline void
_hud_leave(BOOL decrement)
{
    if (decrement) {
        if (--hud.depth == 0) {
            hud_profile_stop();
            if (hud.q_count > 0) {
                hudQ_drain();
            }
        }
    }
    else {
        hud_profile_stop();
    }
}

/*
 * Perform actions required upon every exit from the hudsucker framework.
 *
 * we want to dec hud.depth and check hud.depth==0 before calling hud_profile_stop().
 * hudQ_drain is called when hud.q_count is larger than HUD_MSG_QUEUE_DEPTH/2.
 */
static inline void
_hud_fast_leave(void)
{
    if (--hud.depth == 0) {
        hud_profile_stop();
        if (hud.q_count > (HUD_MSG_QUEUE_DEPTH >> 1)) {
            hudQ_drain();
        }
    }
}

/*
 * Generic accessor functions that are stream/connflow agnostic.
 */

static inline void
uflow_handle(struct hudnode *node, hud_msg_t msg, union uflow *uf, void *data)
{
    hud_msg_log("uflow handle", msg, uf, node, data);
    node->h_s_handler(node, msg, uf, data);
}

static inline void
uflow_handle_lower(struct hudnode *node, hud_msg_t msg,
        union uflow *uf, void *data)
{
    /*
     * Pending async operations can hold a reference to a node beyond the life
     * of the node itself.  Which is fine.  But if the node tries to contact
     * others in the chain, then the messages should be dropped.
     */
    struct hudnode *next = node->below;
    if (next != NULL) {
        hud_msg_log("uflow lower", msg, uf, next, data);
        next->h_s_handler(next, msg, uf, data);
    }
}

static inline void
uflow_handle_upper(struct hudnode *node, hud_msg_t msg,
        union uflow *uf, void *data)
{
    /*
     * Pending async operations can hold a reference to a node beyond the life
     * of the node itself.  Which is fine.  But if the node tries to contact
     * others in the chain, then the messages should be dropped.
     */
    struct hudnode *next = node->above;
    if (next != NULL) {
        hud_msg_log("uflow upper", msg, uf, next, data);
        next->h_s_handler(next, msg, uf, data);
    }
}

static inline void
uflow_handle_default(struct hudnode *node, hud_msg_t msg, union uflow *uf,
        void *data)
{
    hud_msg_log("uflow default", msg, uf, node, data);

    if (IS_HUDCTL_MSG(msg)) {
        uflow_handle_lower(node, msg, uf, data);
    } else if (IS_HUDEVT_MSG(msg)) {
        uflow_handle_upper(node, msg, uf, data);
    } else {
#if HUDFILTER_DEBUG
    /* bad message */
    panic("uflow_handle_default: bad message %s (%d)",
            hud_msg_name_str(msg), msg);
#endif
    }
}

