/* Initialize the hudchain template. */
err_t
hudchain_init(struct hudchain_template *ht)
{
    memset(ht, 0, sizeof(struct hudchain_template));
    return ERR_OK;
}

/* Add a filter (hud_typeid) to the chain. */
err_t
hudchain_add(struct hudchain_template *ht, struct hud_typeid *typeid,
        BOOL deferred)
{
    if (!hudchain_is_member(ht, typeid)) {
        if ((ht->count + 1) >= HUDCHAIN_DEPTH) {
            return ERR_MEM;
        }
        ht->entries[ht->count].typeid = typeid;
        ht->entries[ht->count].deferred = deferred;
        ht->count++;
    }
    return ERR_OK;
}

/* Delete a filter  (hud_typeid) from the chain. */
err_t
hudchain_delete(struct hudchain_template *ht, struct hud_typeid *typeid)
{
    int i;
    for (i = 0; i < ht->count; i++) {
        if (ht->entries[i].typeid == typeid) {
            ht->count--;
            ht->entries[i].typeid = ht->entries[ht->count].typeid;
            ht->entries[i].deferred = ht->entries[ht->count].deferred;
        }
    }
    return ERR_OK;
}

/* Test membership on the chain. */
BOOL
hudchain_is_member(struct hudchain_template *ht, struct hud_typeid *typeid)
{
    int i;
    for (i = 0; (i < ht->count); ++i) {
        if (ht->entries[i].typeid == typeid) {
            return TRUE;
        }
    }
    return FALSE;
}

/*
 * Selection sort a typeid array according to the hudconstraint position value.
 * The speed of selection sort is not a concern as the number of filters in
 * a hudchain is usually small, and is executed most frequently at startup.
 */
#define SWAP(x,y) do { \
    tmp = entries[x]; entries[x] = entries[y]; entries[y] = tmp; \
} while(0)
static void
hudchain_sort(int count, struct hudchain_entry *entries, BOOL clientside)
{
    int i, j;
    struct hudchain_entry tmp;
    INT32 maxval = 0, val;
    int maxpos;
    struct hudfilter_constraint *constraints;

    for (i = count - 1; (i >= 0); --i) {
        maxpos = -1;  /* force maxval and maxpos to be reset */
        for (j = 0; (j <= i); ++j) {
            constraints = &entries[j].typeid->constraint;
            if (clientside) {
                val = constraints->clientside.index;
            } else {
                val = constraints->serverside.index;
            }
            if ((maxpos < 0) || (val > maxval)) {
                maxval = val;
                maxpos = j;
            }
        }
        if (maxpos < i) {
            SWAP(maxpos, i);
        }
    }
}
#undef SWAP

static err_t
hudchain_filter_construct(struct hudchain_template *ht, struct hudnode *upper)
{
    struct hudnode *node = NULL;
    struct hudnode *lower;
    int i;
    err_t err = ERR_OK;

    for (i = 0; (i < ht->count); ++i) {
        ASSERT("valid filter chain", IS_HUDFILTER(ht->entries[i].typeid));

        /* link in the filter */
        lower = node;
        node = hudfilter_new(ht->entries[i].typeid);
        if (node == NULL) {
            err = ERR_MEM;
            goto out;
        }

        /* Save the 'deferred' annotation. */
        HUDNODE_FILTER(node)->base.f_deferred = ht->entries[i].deferred;
        if (lower != NULL) {
            hudnode_connect(lower, node);
        }
    }
    if (node != NULL) {
        hudnode_connect(node, upper);
    }

out:
    if (err != ERR_OK) {
        hudfilter_uninit(lower);
    }
    return err;
}

/* instantiate a new hudchain */
err_t
hudchain_construct(struct hudproxy *proxy, struct profile_list *profile_list)
{
    err_t err;

    /* clientside */
    err = hudchain_filter_construct(&proxy->ht[0], proxy->clientside);
    if (err != ERR_OK) {
        goto out;
    }

    /* serverside */
    err = hudchain_filter_construct(&proxy->ht[1], proxy->serverside);
    if (err != ERR_OK) {
        hudfilter_uninit(proxy->clientside);
        goto out;
    }

     /* add the profile list to the proxy */
    err = profile_list_copy(&proxy->profile_list, profile_list);
    if (err != ERR_OK) {
        hudfilter_uninit(proxy->clientside);
        hudfilter_uninit(proxy->serverside);
        goto out;
    }
out:
    return err;
}

err_t
hudchain_constrain(struct hudchain_template *ht, BOOL clientside)
{
    int i, j;
    struct hudfilter_constraint *constraints;
    struct hud_typeid **require, **preclude;

    err_t err = ERR_OK;

    for (i = 0; (i < ht->count); ++i) {
        constraints = &ht->entries[i].typeid->constraint;
        require = clientside ? constraints->clientside.require :
            constraints->serverside.require;
        preclude = clientside ? constraints->clientside.preclude :
            constraints->serverside.preclude;
        /* Any one of the requires is sufficient for success. */
        if ((require == NULL) || (require[0] == NULL)) {
            goto found;
        }
        for (j = 0; require[j] != NULL; ++j) {
            if (hudchain_is_member(ht, require[j])) {
                goto found;
            }
        }
        for (j = 0; require[j] != NULL; ++j) {
            printf("hudchain missing required %s filter: %s\n",
                    clientside ? "clientside" : "serverside",
                    require[j]->name);
        }
        err = ERR_ARG;
        goto out;
found:
        /* precludes */
        for (j = 0; ((preclude != NULL) && (preclude[j] != 0)); ++j) {
            if (hudchain_is_member(ht, preclude[j])) {
                printf("hudchain contains precluded %s filter: %s\n",
                        clientside ? "clientside" : "serverside",
                        preclude[j]->name);
                err = ERR_ARG;
                goto out;
            }
        }
    }

    /* enforce ordering constraints */
    hudchain_sort(ht->count, ht->entries, clientside);/* select the appropriate hudchain */

out:
    return err;
}

err_t
hudchain_select(struct listener *listener, struct profile_list *profile_list, 
        struct hudproxy **pproxy)
{
    struct hudchain_template *cs, *ss;
    struct hud_typeid *proxy_id;
    struct hudproxy *proxy = NULL;
    err_t err = ERR_OK;

    ASSERT("proxy not NULL", pproxy != NULL);

    /* Allocate a new proxy object. */
    proxy = hudproxy_alloc();
    if (proxy == NULL) {
        err = ERR_MEM;
        goto out;
    }

    cs = &proxy->ht[0];
    ss = &proxy->ht[1];

    /* get the hudchain template for this profile list */
    err = profile_list_hudchain_select(NULL, profile_list, cs, ss, &proxy_id);
    if (err != ERR_OK) {
        /* The proxy object has not yet been set up; free. */
        umem_free(proxy, sizeof(struct hudproxy), M_PROXY);
        proxy = NULL;
        goto out;
    }

    /*
     * Perform basic setup for this proxy type.
     */
    if ((err = hudproxy_setup(proxy, proxy_id)) != ERR_OK) {
        err = ERR_MEM;
        /* The proxy object has not yet been set up; free. */
        umem_free(proxy, sizeof(struct hudproxy), M_PROXY);
        proxy = NULL;
        goto out;
    }
    /* check clientside filter constraints */
    if ((err = hudchain_constrain(cs, TRUE)) != ERR_OK) {
        goto out;
    }

    /* check serverside filter constraints */
    if ((err = hudchain_constrain(ss, FALSE)) != ERR_OK) {
        goto out;
    }

    /* construct hudchain from the template */
    if ((err = hudchain_construct(proxy, profile_list)) != ERR_OK) {
        goto out;
    }

out:
    if (err == ERR_OK) {
        if (pproxy != NULL) {
            hudproxy_set_listener_name(proxy, listener);
            *pproxy = proxy;
        }
    } else {
        hudproxy_uninit(proxy);
    }
    return err;
}

struct hudproxy *
hudproxy_clone(struct hudproxy *h, struct profile_list *profile_list,
        const char *listener_name, BOOL set_proxy_name)
{
    struct hudproxy *proxy = hudproxy_new(h->typeid);
    struct hudnode *n;

    if (proxy == NULL) {
        goto out;
    }

    /* Inherit unless otherwise specified. */
    if (listener_name == NULL) {
        listener_name = h->listener_name;
    }
    if (profile_list == NULL) {
        profile_list = &h->profile_list;
    }

    if ((listener_name != NULL) && (listener_name[0] != '\0')) {
        proxy->listener_name = string_cache_create(listener_name);
    }

    if (set_proxy_name && (h->proxy_name != NULL) &&
            (h->proxy_name[0] != '\0')) {
        if (hudproxy_set_proxy_name(proxy, h->proxy_name) != ERR_OK) {
            goto fail;
        }
    }

    for (n = h->clientside->below; n != NULL; n= n->below) {
        hudchain_add(&proxy->ht[0], HUDNODE_TYPEID(n), FALSE);
    }
    for (n = h->serverside->below; n != NULL; n = n->below) {
        hudchain_add(&proxy->ht[1], HUDNODE_TYPEID(n), FALSE);
    }
    /* XXX Could add the deferred list here too. */
    hudchain_sort(proxy->ht[0].count, proxy->ht[0].entries, TRUE);
    hudchain_sort(proxy->ht[1].count, proxy->ht[1].entries, FALSE);

    /* construct hudchain from the template */
    if (hudchain_construct(proxy, profile_list) != ERR_OK) {
        goto fail;
    }
    if (hudproxy_init(proxy) != ERR_OK) {
        goto fail;
    }
    goto out;
fail:
    hudproxy_release(proxy);
    proxy = NULL;
out:
    return proxy;
}

/*
 * Require hudchain constructions.
 */
static err_t
hud_check(void)
{
    int i;

    if (is_standalone_tmm()) {
        goto out;
    }

