static GLOBALSET umem_handle_t streamflow_cache;

/*
 * Initialize the stream infrastructure
 */
static err_t
flow_stream_init(void)
{
    err_t err = ERR_OK;

    err = umem_cache_create(&streamflow_cache, "streamflow",
            sizeof(struct streamflow), 0, NULL, NULL, NULL, NULL, 0);
    if (err != ERR_OK) {
        printf("%s: Unable to initialize stream flow cache\n", __func__);
    }
    return err;
}
