    register unsigned long result;                              \
    __asm__ __volatile__ (                                      \
        "movdqu %1, %%xmm1\t\n\t"                               \
        "movdqu %2, %%xmm0\t\n\t"                               \
        "pcmpeqd %%xmm1, %%xmm0\t\n\t"                          \
        "pmovmskb %%xmm0, %%rax\t\n\t"                          \
        "movdqu %3, %%xmm1\t\n\t"                               \
        "movdqu %4, %%xmm0\t\n\t"                               \
        "pcmpeqd %%xmm1, %%xmm0\t\n\t"                          \
        "pmovmskb %%xmm0, %0\t\n\t"                             \
        "and %%rax, %0\t\n\t"                                   \
        "xor $0xFFFF, %0\t\n\t"                                 \
        "xor %5, %6\t\n\t"                                      \
        "or %6, %0\t\n\t"                                       \
        :"=&r" (result)                                         \
        :"m" (*(&(cf)->remote_addr)), "m" (*(&(key)->remote_addr)), \
         "m" (*(&(cf)->local_addr)), "m" (*(&(key)->local_addr)),   \
         "r" ((*(UINT64 *)&(cf)->remote_port) & 0xFFFFFFFFFF),  \
         "r" ((*(UINT64 *)&(key)->remote_port) & 0xFFFFFFFFFF)  \
        :"xmm0", "xmm1", "rax", "memory"                        \
    );                                                          \
    result;                                                     \
})
#else
/*
 * Returns 0 if the key matches the connflow, non-zero if it does not.
 * This is here because it is heavily dependent on field size and order,
 * and must be updated if the primary match fields change.
 *
 * The address fields are compared separately, rather than using bcmp()
 * to compare all the fields at once, because an ip_addr_t is the
 * largest data size that bcmp() will compare inline; anything larger
 * requires a function call.
 */
#define CONNFLOW_KEY_MISMATCH(cf, key) (                           \
        inet_addr_not_equal((key)->remote_addr, (cf)->remote_addr, \
                CONNFLOW_ADDR_SIZE(cf)) |                          \
        inet_addr_not_equal((key)->local_addr, (cf)->local_addr,   \
                CONNFLOW_ADDR_SIZE(cf)) |                          \
        bcmp(&(cf)->remote_port, &(key)->remote_port,              \
                (offsetof(struct flow_key, ipproto) -              \
                 offsetof(struct flow_key, remote_port) + sizeof(UINT8))))
#endif /* __SSE2__ */

#define CONNFLOW_FLOW_KEY(cf) ((struct flow_key *)&((cf)->remote_addr))

#define CONNFLOW_TOP_CTX(cf)                                                \
    (((cf)->top_node == NULL) ? NULL : HUDNODE_CTX((cf)->top_node))
#define CONNFLOW_BOTTOM_CTX(cf)                                             \
    (((cf)->bottom_node == NULL) ?  NULL : HUDNODE_CTX((cf)->bottom_node))
#define CONNFLOW_FILTER(cf)                                                 \
    (((cf)->bottom_node == NULL) ? NULL : HUDNODE_FILTER((cf)->bottom_node))
#define CONNFLOW_PROXY(cf)                                                  \
    (((cf)->bottom_node == NULL) ? NULL : HUDNODE_PROXY((cf)->bottom_node))

/* CONNFLOW flags */
#define CONNFLOW_FLAG_IPV6          0x00000001  /* IPv6-addressed flow  */
#define CONNFLOW_FLAG_L2FORWARD     0x00000002  /* L2 forward this flow */
#define CONNFLOW_FLAG_COUNTED       0x00000004  /* this conn was counted */
#define CONNFLOW_FLAG_EXPIRED       0x00000008  /* connflow expired     */
#define CONNFLOW_FLAG_NOEXPIRE      0x00000010  /* Don't reap this flow */
#define CONNFLOW_FLAG_INUSE         0x00000020  /* flow is in the table (sanity) */
#define CONNFLOW_FLAG_MIRRORED      0x00000040  /* flow is mirrored */
#define CONNFLOW_FLAG_NOT4U         0x00000080  /* Not 4U! */
#define CONNFLOW_FLAG_NOPROXYMSS    0x00000100  /* flow must not proxy MSS */
#define CONNFLOW_FLAG_TRANSPARENT   0x00000200  /* preserve source address */
#define CONNFLOW_FLAG_NOTRANSLATE   0x00000400  /* preserve destination address */
#define CONNFLOW_FLAG_NOPORTTRANS   0x00000800  /* preserve destination port */
#define CONNFLOW_FLAG_CLONE         0x00001000  /* clone pkts for this flow */
#define CONNFLOW_FLAG_DROP          0x00002000  /* no reset on HUDCTL_ABORT */
#define CONNFLOW_FLAG_AUTH          0x00004000  /* AUTH in use */
#define CONNFLOW_FLAG_TCPOPT_TS     0x00008000  /* flow has TCP timestamps */
#define CONNFLOW_FLAG_MIRROR_PKTS   0x00010000  /* mirror data packets */
#define CONNFLOW_FLAG_TRUNK_IDX_SET 0x00020000  /* is index of trunk set? */
#define CONNFLOW_FLAG_RESELECT_MAC  0x00040000  /* Check ingress src MAC */
#define CONNFLOW_FLAG_RESELECT      0x00080000  /* Reselect the peer's pmbr */
#define CONNFLOW_FLAG_NOCONNPOOL    0x00100000  /* don't connection pool */
#define CONNFLOW_FLAG_DETACH        0x00200000  /* detach after response done */
#define CONNFLOW_FLAG_PVA           0x00400000  /* flow is currenty in PVA */
#define CONNFLOW_FLAG_DYING         0x00800000  /* flow got ABORT/TEARDOWN */
#define CONNFLOW_FLAG_WAIT_HA_CTX   0x01000000  /* flow waiting for HA CTX */
#define CONNFLOW_FLAG_RATESHAPER    0x02000000  /* rate shaper flow */
#define CONNFLOW_FLAG_TCPDUMP       0x04000000  /* tcpdump flow */
#define CONNFLOW_FLAG_DOUBLE_LB     0x08000000  /* LB'd to both dest and nexthop pmbr */
#define CONNFLOW_FLAG_LISTENER      0x10000000  /* a dependent listener exists */
#define CONNFLOW_FLAG_HOST          0x20000000  /* flow associated with host  */
#define CONNFLOW_FLAG_MODIFIED_PEER 0x40000000  /* true peer isn't remote_addr*/
#define CONNFLOW_FLAG_NOMATCH       0x80000000  /* do not use in flow lookups */
#define CONNFLOW_FLAG_L2_TRANS     0x100000000ULL /* preserve L2 addresses */
#define CONNFLOW_FLAG_DYNAMIC      0x200000000ULL  /* has dynamic hudnode opaque. */
#define CONNFLOW_FLAG_BWC          0x400000000ULL  /* BWC shaper */

#define CONNFLOW_FLAG_SHAPER (CONNFLOW_FLAG_RATESHAPER | CONNFLOW_FLAG_BWC)
#define CONNFLOW_FLAG_CMP_PEER     0x800000000ULL  /* has a CMP peer. */
#define CONNFLOW_FLAG_FW_MODULE   0x1000000000ULL  /* fw opaque_ctx valid. */
#define CONNFLOW_FLAG_NOT4U2      0x2000000000ULL  /* RESERVED !4U */
#define CONNFLOW_FLAG_PROXY_FREE  0x4000000000ULL  /* Use proxy->flow_free. */
#define CONNFLOW_FLAG_NWDOS_CFG   0x8000000000ULL  /* has nwdos vectors */
#define CONNFLOW_FLAG_NSH        0x10000000000ULL  /* NSH in flow. */
#define CONNFLOW_FLAG_MCAST      0x20000000000ULL /* Multicast flow */
#define CONNFLOW_FLAG_PRIORITY_OVERRIDE \
                                 0x40000000000ULL /* priority override by iRule */
#define CONNFLOW_FLAG_MPTCP      0x80000000000ULL  /* MPTCP flow. */
#define CONNFLOW_FLAG_DOSWL_HIT  0x100000000000ULL /* DoS whitelist hit */
#define CONNFLOW_FLAG_DOSWL_DONE 0x200000000000ULL /* DoS whitelist checked */
#define CONNFLOW_FLAG_CMP_NOFWD  0x400000000000ULL /* Do not CMP redirect. */
#define CONNFLOW_FLAG_FW_ACTION_DECISIVE \
                                 0x800000000000ULL /* global/rtdom action
                                                    * is Accept Decisive. */
#define CONNFLOW_FLAG_SWEEP_HIT  0x1000000000000ULL /* DoS Sweep hit */
#define CONNFLOW_FLAG_FLOOD_HIT  0x2000000000000ULL /* DoS Flood hit */
#define CONNFLOW_FLAG_PEM_FWD    0x4000000000000ULL  /* Flow is PEM forwarded */
#define CONNFLOW_FLAG_IDLE_TIMEOUT \
                                 0x8000000000000ULL  /* Idle timeout policy set */
#define CONNFLOW_FLAG_IPIDR     0x10000000000000ULL /* Flow slowed by ipidr */
#define CONNFLOW_FLAG_IPIDR_FIRST_PACKET  0x20000000000000ULL /* Flow slowed by ipidr */

#define CONNFLOW_FLAG_DOSSPVA_GWL_HIT      0x40000000000000ULL /* sPVA srcIP Global WL Hit */
#define CONNFLOW_FLAG_DOSSPVA_VWL_HIT      0x80000000000000ULL /* sPVA srcIP Virtual WL hit*/
#define CONNFLOW_FLAG_DOSSPVA_WL_DONE      0x100000000000000ULL /* sPVA srcIP WL Done */
#define CONNFLOW_FLAG_TRACE    0x200000000000000ULL  /* TCP tracing. */
#define CONNFLOW_FLAG_PVA_ASYMMETRIC     0x400000000000000ULL  /* ePVA client/server flows in 2 HSBs */
#define CONNFLOW_FLAG_MIRRORED_TUNNEL    0x800000000000000ULL  /* Treat as mirrored in listener lookup */
#define CONNFLOW_FLAG_FFWD     0x1000000000000000ULL  /* has ffwd entry. */
#define CONNFLOW_FLAG_TRANS_CONF    0x2000000000000000ULL  /* transport config. */
#define CONNFLOW_FLAG_PVA_INSERT    0x4000000000000000ULL  /* PVA insert for management ring */

/* 0 bits remaining in the 62 bit connflow flags. */

/* set flow flag */
#define flow_set_flag(cf, f) ( \
    (cf)->flags |= (f))

/* clear flow flag */
#define flow_clear_flag(cf, f) ( \
    (cf)->flags &= ~(UINT64)(f))

/* test flow flag */
#define flow_test_flag(cf, f) ( \
    ((cf)->flags & (f)) != 0)

