};

#define FLOW_PKTCLASS_IN_INIT(_in, _src_listener, _listener, _ifc_in, \
        _from_sweeper, _flow_epoch, _reclassify) do { \
    (_in).src_listener = (_src_listener); \
    (_in).ifc_in = (_ifc_in); \
    (_in).from_sweeper = (_from_sweeper); \
    (_in).flow_epoch = (_flow_epoch); \
    (_in).reclassify = (_reclassify); \
    (_in).spolicy_type = SPOLICY_LAST; \
    (_in).enforce_dos = FALSE; \
    (_in).sendtovs_check = FALSE; \
    (_in).skip_global_default_rule = FALSE; \
    (_in).listener = (_listener); \
} while(0)

#define FLOW_PKTCLASS_OUT_INIT(_out, _opaque, _row, _cat, \
        _fw_global_rtdom_action, _src_geo, _dst_geo) do { \
    (_out).opaque = (_opaque); \
    (_out).pc_row = (_row); \
    (_out).pc_cat = (_cat); \
    (_out).fw_global_rtdom_action = (_fw_global_rtdom_action); \
    (_out).src_geo = (_src_geo); \
