    UINT32 flags = parent_cf->flags;

    flags &= CONNFLOW_FLAG_IPV6          |
             CONNFLOW_FLAG_L2FORWARD     |
             CONNFLOW_FLAG_HOST          |
             CONNFLOW_FLAG_COUNTED       |
             CONNFLOW_FLAG_MIRRORED      |
             CONNFLOW_FLAG_TRANSPARENT   |
             CONNFLOW_FLAG_NOTRANSLATE   |
             CONNFLOW_FLAG_RESELECT      |
             CONNFLOW_FLAG_TCPDUMP       |
             CONNFLOW_FLAG_DOUBLE_LB;
    return flags;
}

